import { summary, applyAction, money, proportionalProfit } from './model.js';

import { api, loadWorkspace, setCsrf, yuanToCents } from './api.js';
const initial = await loadWorkspace();
let state=initial.state, revision=initial.revision;
const session=initial.session;
const currentDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const ui={month:state.mode==='demo'?'2026-10':currentDate().slice(0,7),role:session.user.role==='owner'?'老板':'财务',page:'overview',customer:'',account:'',search:''};
let submitting=false,pendingCommand=null;
document.querySelector('#monthPicker').value=ui.month;
document.querySelector('.sidebar-note').innerHTML='<span class="status-dot"></span>共享测试账本<small>数据库保存 · 登录后访问</small>';
document.querySelector('.demo-badge').textContent=state.mode==='demo'?'联机测试 · 虚构演示数据':'联机测试 · 空白起账';
document.querySelector('.app-footer').textContent='开发测试版 · 数据保存在当前服务器 · 真实导入、期初建账与历史更正仍在开发';
document.querySelector('#switchRole').textContent='退出';
document.querySelector('#switchRole').title='退出登录';
document.querySelector('#switchRole').setAttribute('aria-label','退出登录');
document.querySelector('#helpButton').setAttribute('aria-label','使用说明');

const names={overview:'经营概览',accounts:'账户流水',purchases:'上游与采购',sales:'客户与销售',inventory:'库存与串号',expenses:'费用与票据',profit:'利润报表',imports:'导入与设置'};
const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',accounts:'M3 7h18v13H3z M3 7l2-4h14l2 4 M3 11h18 M15 15h3',purchases:'M3 9l9-6 9 6v12H3z M9 21v-8h6v8',sales:'M4 5h16v15H4z M8 3v4 M16 3v4 M8 11h8 M8 15h5',inventory:'M3 7l9-4 9 4-9 4z M3 7v10l9 4 9-4V7 M12 11v10',expenses:'M6 3h12v18l-3-2-3 2-3-2-3 2z M9 8h6 M9 12h6',profit:'M4 20V4 M4 20h17 M8 16v-4 M13 16V8 M18 16V5',imports:'M4 8V4h16v4 M12 3v11 M8 10l4 4 4-4 M4 14v6h16v-6',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',bank:'M3 9l9-6 9 6z M5 10v8 M10 10v8 M15 10v8 M19 10v8 M3 21h18',check:'M5 12l4 4L19 6',search:'M16 16l5 5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0'};
const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.overview}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cash=n=>`¥${money(n)}`;
const get=(key,id)=>state[key]?.find(x=>x.id===id);
const name=(key,id)=>esc(get(key,id)?.name||id||'—');
const byDate=(a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id,undefined,{numeric:true});
const inMonth=r=>r.date?.startsWith(ui.month);
const btn=(text,action,kind='secondary',id='')=>`<button class="button ${kind}" data-action="${action}" data-id="${esc(id)}">${esc(text)}</button>`;
const pill=(text,kind='neutral')=>`<span class="pill ${kind}">${esc(text)}</span>`;
const table=(headers,rows,empty='暂无记录')=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}"><div class="empty-state">${esc(empty)}</div></td></tr>`}</tbody></table></div>`;
const panel=(title,body,action='',sub='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<div class="panel-subtitle">${sub}</div>`:''}</div>${action}</div>${body}</section>`;
const amount=n=>`<span class="amount ${n<0?'negative':''}">${cash(n)}</span>`;
const pageHead=(eyebrow,title,sub,actions='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="page-subtitle">${sub}</p></div><div class="page-actions">${actions}</div></div>`;
const kpi=(label,value,meta,page,accent=false)=>`<div class="kpi-card ${accent?'accent':''}" role="button" tabindex="0" data-go="${page}"><div class="kpi-label">${label}${icon(page)}</div><div class="kpi-value"><small>¥</small>${money(value)}</div><div class="kpi-meta">${meta}</div></div>`;
const accountOptions=(selected='')=>state.accounts.map(a=>`<option value="${a.id}" ${a.id===selected?'selected':''}>${esc(a.name)} · ${cash(a.balance)}</option>`).join('');
const entityOptions=(key,selected='')=>state[key].map(x=>`<option value="${x.id}" ${selected===x.id?'selected':''}>${esc(x.name)}</option>`).join('');
const statusSale=s=>s.returned?pill('已退货','neutral'):s.paid>=s.amount?pill('已收齐','success'):s.paid?pill('部分回款','warning'):pill('待收款','info');
const statusPurchase=p=>pill({locked:'已锁货 · 待发',shipped:'已发货 · 在途',received:'已入库'}[p.status],{locked:'warning',shipped:'info',received:'success'}[p.status]);
const typeNames={opening:'期初余额',receipt:'客户回款',transfer_in:'内部转入',transfer_out:'内部转出',boss_in:'老板垫资',boss_repay:'归还老板',expense:'经营支出',supplier_pay:'上游预付款',boss_pay:'老板代付',tax:'月度税费',freight_adjust:'运费补差',purchase_lock:'采购锁货',purchase_ship:'上游发货',purchase_receive:'采购入库',sale_return:'客户退货',sale_create:'销售出库',invoice:'发票登记',close_month:'月份关账',reopen_month:'反关账',master_create:'基础资料新增',account_rename:'账户改名'};
const ledgerRows=rows=>rows.map(r=>`<tr><td>${esc(r.date)}<span class="muted">${esc(r.id)}</span></td><td>${name('accounts',r.accountId)}</td><td>${pill(typeNames[r.type]||r.type)}</td><td class="right ${r.amount>=0?'positive':'negative'}">${r.amount>0?'+':''}${cash(r.amount)}</td><td>${esc(r.note)}</td></tr>`);
async function refresh(showMessage=false){
  try{const data=await api('state');if(data.revision>=revision){state=data.state;revision=data.revision;}render();if(showMessage)toast('已读取最新账本');}
  catch(e){if(e.status===401)location.replace('/login.html');else if(showMessage)toast(e.message);else document.querySelector('.sync-status').textContent='连接中断，请刷新重试';}
}
async function saveCommand(action){
  const serialized=JSON.stringify(action);
  if(pendingCommand&&pendingCommand.serialized!==serialized)throw new Error('上一笔保存结果未确认，请先恢复原内容重试，避免重复记账。');
  pendingCommand ||= {key:crypto.randomUUID(),revision,action,serialized};
  try{
    const {key,revision:version,action:payload}=pendingCommand;
    const result=await api('commands',{key,revision:version,action:payload});
    if(result.revision>=revision){state=result.state;revision=result.revision;}pendingCommand=null;
    return result;
  }catch(e){
    if(!e.uncertain)pendingCommand=null;
    if(e.status===409)await refresh();
    if(e.status===401)location.replace('/login.html');
    throw e;
  }
}
let toastTimer;function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),3500);}
function go(page){location.hash=page;ui.search='';ui.customer='';ui.account='';closeMenu();if(ui.page===page)render();}
function closeMenu(){document.querySelector('#sidebar').classList.remove('open');document.querySelector('#overlay').classList.remove('visible');}
function cashChart(){const [year,month]=ui.month.split('-').map(Number);const end=ui.month===currentDate().slice(0,7)?Number(currentDate().slice(-2)):new Date(Date.UTC(year,month,0)).getUTCDate();const days=Array.from({length:7},(_,i)=>new Date(Date.UTC(year,month-1,end-6+i)).toISOString().slice(0,10));const values=days.map(d=>{const rs=state.ledger.filter(r=>r.date===d&&!r.type.startsWith('transfer')&&r.type!=='opening');return {in:rs.reduce((s,r)=>s+Math.max(0,r.amount),0),out:rs.reduce((s,r)=>s+Math.max(0,-r.amount),0)};});const max=Math.max(1,...values.flatMap(v=>[v.in,v.out]));return `<div class="compact-chart">${values.map((v,i)=>`<div class="bar-day" title="${days[i]}：流入 ${cash(v.in)}，流出 ${cash(v.out)}"><div class="bar-pair"><i style="height:${Math.max(2,v.in/max*100)}%"></i><i class="out" style="height:${Math.max(2,v.out/max*100)}%"></i></div><span>${days[i].slice(5).replace('-','/')}</span></div>`).join('')}</div><div class="data-note" style="padding:10px 20px 16px">不含期初余额及内部转账</div>`;}
function profitBreakdown(s){return `<div class="panel-body"><div class="formula-row"><span>回款及余额抵扣确认</span><strong>${cash(s.salesProfit)}</strong></div><div class="formula-row"><span>退货利润冲回</span><strong>− ${cash(s.returnReversal)}</strong></div><div class="formula-row"><span>本月已付经营费用</span><strong>− ${cash(s.expenses)}</strong></div><div class="formula-row"><span>手工登记税费</span><strong>− ${cash(s.tax)}</strong></div><div class="formula-row"><span>运费及其他调整</span><strong>− ${cash(s.adjustments)}</strong></div><div class="formula-total"><span>公司利润</span>${amount(s.profit)}</div></div>`;}
function overview(){const s=summary(state,ui.month);const recent=[...state.ledger].filter(inMonth).sort(byDate).slice(0,5);const ps=state.purchases.filter(p=>p.status!=='received');return pageHead('WORKSPACE / OVERVIEW','经营概览',`${ui.month.replace('-',' 年 ')} 月 · 资金余额为当前余额，利润按所选月份统计`,btn('登记付款','expense')+btn('＋ 登记回款','receipt','primary'))+
`<div class="kpi-grid">${kpi('账户总余额',s.totalCash,'2 个对公账户 · 4 个业务账户','accounts')}${kpi('本月公司利润',s.profit,'按回款确认，已扣费用及税费','profit',true)}${kpi('客户待收款',s.receivables,'客户欠款与可用余额分别展示','sales')}${kpi('上游可用余额',s.supplierAvailable,'锁货扣减，入库不重复扣款','purchases')}</div><div class="summary-strip"><button data-go="inventory">库存金额 <strong>${cash(s.inventoryValue)}</strong></button><button data-go="purchases">在途货品 <strong>${s.inTransitQty} 台</strong></button><button data-go="accounts">公司欠老板 <strong>${cash(s.bossOwed)}</strong></button><button data-go="sales">客户可用余额 <strong>${cash(s.customerCredit)}</strong></button></div>
<div class="dashboard-grid"><div class="dashboard-main">${panel('资金分布',`<div class="account-list">${state.accounts.map(a=>`<div class="account-row"><div class="account-icon ${a.type==='corporate'?'business':'personal'}">${icon(a.type==='corporate'?'bank':'accounts')}</div><div class="account-info"><strong>${esc(a.name)}</strong><small>${a.type==='corporate'?'对公账户':'业务专用账户'}</small></div><div class="account-amount">${cash(a.balance)}</div><button class="text-button" data-action="accountDetail" data-id="${a.id}">明细 →</button></div>`).join('')}</div>`,btn('账户互转','transfer','ghost small'))}${panel('最近资金流水',table(['日期 / 单号','账户','类型','金额','备注'],ledgerRows(recent)),`<button class="text-button" data-go="accounts">全部流水 →</button>`)}</div><div class="dashboard-rail"><section class="panel"><div class="profit-head"><div class="small-label">本月利润 · ${ui.month}</div><div class="big-number">${cash(s.profit)}</div><p class="data-note">每笔数字，都能追溯到业务</p></div>${profitBreakdown(s)}<div style="padding:0 20px 20px">${btn('查看利润明细 →','profitDetail','secondary full-width')}</div></section>${panel('近 7 日账户收付',cashChart(),'<div class="chart-key"><span><i></i>流入</span><span><i class="out"></i>流出</span></div>')}${panel('待处理',`<div>${[{n:ps.filter(p=>p.status==='shipped').length,t:'在途采购待入库',d:'到货时直接填写运费',go:'purchases'},{n:state.sales.filter(x=>!x.returned&&x.paid<x.amount).length,t:'销售待回款',d:'登记总额，系统自动抵扣',go:'sales'}].map(x=>`<button class="list-row button-row" data-go="${x.go}"><span class="task-count">${x.n}</span><span class="task-text"><strong>${x.t}</strong><small>${x.d}</small></span>${icon('arrow')}</button>`).join('')}</div>`)}</div></div>`;}
function accounts(){const s=summary(state,ui.month);let rows=state.ledger.filter(inMonth).filter(r=>!ui.account||r.accountId===ui.account).filter(r=>`${r.note} ${r.id} ${get('accounts',r.accountId)?.name}`.includes(ui.search)).sort(byDate);return pageHead('MONEY / ACCOUNTS','账户流水','6 个账户统一管理；内部转账与老板垫款分开记录',btn('老板往来','bossMenu')+btn('账户互转','transfer')+btn('＋ 登记回款','receipt','primary'))+`<div class="kpi-grid">${kpi('全部账户',s.totalCash,'当前账面余额','accounts')}${kpi('对公账户',state.accounts.filter(a=>a.type==='corporate').reduce((n,a)=>n+a.balance,0),'2 个账户','accounts')}${kpi('业务卡',state.accounts.filter(a=>a.type!=='corporate').reduce((n,a)=>n+a.balance,0),'4 个账户','accounts')}${kpi('公司欠老板',s.bossOwed,'垫入 + 代付 − 已归还','accounts')}</div>`+panel('收付款明细',`<div class="table-toolbar"><input class="search-input" id="search" aria-label="搜索流水" placeholder="搜索备注、账户或单号" value="${esc(ui.search)}"><select class="account-select" id="accountFilter" aria-label="筛选账户"><option value="">全部账户</option>${accountOptions(ui.account)}</select>${btn('登记费用','expense','small secondary')}${btn('上游打款','supplier_pay','small secondary')}</div>${table(['日期 / 单号','账户','业务类型','金额','备注'],ledgerRows(rows))}`,pill(`${rows.length} 条`));}
function purchases(){const s=summary(state,ui.month);return pageHead('PURCHASE / SUPPLIERS','上游与采购','从打款、锁货到入库，核对钱与货的每一步',btn('向上游打款','supplier_pay')+btn('＋ 登记锁货','purchase_lock','primary'))+`<div class="three-column">${state.suppliers.map(p=>`<div class="panel panel-body"><div class="row between"><strong>${esc(p.name)}</strong>${pill('预付供应商','info')}</div><div class="submetric">当前可用余额</div><div class="big-number" style="margin:10px 0">${cash(p.available)}</div><button class="text-button" data-action="supplier_pay" data-id="${p.id}">登记打款 →</button></div>`).join('')}</div><div style="height:20px"></div>`+panel('采购履约',table(['采购单 / 锁货日期','供应商 / 商品','数量','采购金额','履约状态','操作'],state.purchases.map(p=>`<tr><td><strong>${esc(p.id)}</strong><span class="muted">${p.lockedDate}</span></td><td>${name('suppliers',p.supplierId)}<span class="muted">${name('products',p.productId)}</span></td><td>${p.qty} 台</td><td class="right">${amount(p.qty*p.unitPrice)}</td><td>${statusPurchase(p)}${p.shippedDate?`<span class="muted">${p.shippedDate} 发出${p.receivedDate?' · '+p.receivedDate+' 到货':''}</span>`:''}</td><td><div class="table-actions">${p.status==='locked'?`<button data-action="purchase_ship" data-id="${p.id}">确认发货</button>`:p.status==='shipped'?`<button data-action="purchase_receive" data-id="${p.id}">确认入库</button>`:`<button data-action="purchaseDetail" data-id="${p.id}">入库详情</button>`}</div></td></tr>`)),pill(`在途 ${s.inTransitQty} 台`))+`<div class="notice" style="margin-top:18px">锁货时扣减上游可用余额；到货只更新库存和成本。进货运费在入库页面填写，无须另记一单。</div>`;}
function sales(){const rows=state.sales.filter(s=>!ui.customer||s.customerId===ui.customer).filter(s=>`${s.id} ${s.sn} ${get('products',s.productId)?.name}`.includes(ui.search)).sort(byDate);return pageHead('SALES / CUSTOMERS','客户与销售','客户看总欠款，系统按销售日期自动分配回款',btn('登记销售','sale_create')+btn('＋ 登记回款','receipt','primary',ui.customer))+`<div class="customer-cards">${state.customers.map(c=>`<button class="customer-card ${ui.customer===c.id?'selected':''}" data-action="customerFilter" data-id="${c.id}"><div class="row between"><strong>${esc(c.name)}</strong>${pill(c.balance<0?'客户余额':'应收',''+(c.balance<0?'success':'neutral'))}</div><span class="amount">${cash(Math.abs(c.balance))}</span><small class="muted">${c.balance<0?'后续拿货可直接抵扣':'账期 '+(c.termDays||3)+' 天 · 按总额核对'}</small></button>`).join('')}</div>`+panel(ui.customer?`${name('customers',ui.customer)} · 销售账单`:'全部销售',`<div class="table-toolbar"><input id="search" class="search-input" aria-label="搜索销售" placeholder="搜索商品、串号或单号" value="${esc(ui.search)}">${ui.customer?btn('查看全部客户','clearCustomer','ghost small'):''}<span class="data-note">包括历史未结销售，金额以当前状态为准</span></div>${table(['日期 / 销售单','客户 / 商品','销售金额','已收 / 已抵扣','回款状态','操作'],rows.map(s=>`<tr><td>${s.date}<span class="muted">${esc(s.id)}</span></td><td>${name('customers',s.customerId)}<span class="muted">${name('products',s.productId)} · ${esc(s.sn)}</span></td><td class="right">${amount(s.amount)}</td><td class="right">${cash(s.paid)}<div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,s.paid/s.amount*100)}%"></div></div></td><td>${statusSale(s)}</td><td><div class="table-actions"><button data-action="saleDetail" data-id="${s.id}">明细</button>${!s.returned?`<button data-action="sale_return" data-id="${s.id}">退货</button>`:''}</div></td></tr>`))}`,pill(`${rows.length} 单`));}
function inventory(){const rows=state.inventory.filter(i=>`${i.sn} ${get('products',i.productId)?.name}`.includes(ui.search));const s=summary(state,ui.month);return pageHead('STOCK / SERIAL NUMBERS','库存与串号','每台相机对应实际采购成本，进货运费随入库分摊',btn('查看在途采购','toPurchases'))+`<div class="summary-strip"><span>在库数量 <strong>${s.inventoryQty} 台</strong></span><span>在库成本 <strong>${cash(s.inventoryValue)}</strong></span><span>在途 <strong>${s.inTransitQty} 台</strong></span><span>当前支持串号商品</span></div>`+panel('单台商品档案',`<div class="table-toolbar"><input id="search" class="search-input" aria-label="搜索串号" placeholder="输入串号或商品名称" value="${esc(ui.search)}"><span class="data-note">DEMO 开头均为虚构串号</span></div>${table(['商品','唯一串号','入库日期','单台到货成本','状态','操作'],rows.map(i=>`<tr><td>${name('products',i.productId)}</td><td class="sn-code">${esc(i.sn)}</td><td>${esc(i.date||'期初')}</td><td class="right">${amount(i.cost)}</td><td>${pill(i.status==='in_stock'?'在库':'已售',i.status==='in_stock'?'success':'neutral')}</td><td><button class="text-button" data-action="serialDetail" data-id="${i.id}">查看轨迹 →</button></td></tr>`))}`);}
function expenses(){const s=summary(state,ui.month);return pageHead('EXPENSES / INVOICES','费用与票据','日常费用按支付月份计入；发票登记与月度税费分别记录',btn('登记发票','invoice')+btn('填写月度税费','tax')+btn('＋ 登记费用','expense','primary'))+`<div class="three-column"><div class="panel panel-body"><div class="small-label">本月已付公司费用</div><div class="big-number" style="margin-top:10px">${cash(s.expenses)}</div><div class="submetric">不重复包含已进入商品成本的运费</div></div><div class="panel panel-body"><div class="row between"><span class="small-label">本月手工税费</span>${state.taxes[ui.month]===undefined?pill('待填写','warning'):pill('已登记','success')}</div><div class="big-number" style="margin-top:10px">${cash(s.tax)}</div><div class="submetric">登记后扣减所选月份利润</div></div><div class="panel panel-body"><div class="small-label">本月运费及其他调整</div><div class="big-number" style="margin-top:10px">${cash(s.adjustments)}</div><button class="text-button" data-action="freight_adjust" style="margin-top:10px">核对运费补差 →</button></div></div><div style="height:20px"></div>`+panel('公司费用明细',table(['付款日期','费用类别','支付来源','金额','说明'],state.expenses.filter(inMonth).sort(byDate).map(e=>`<tr><td>${e.date}</td><td>${esc(e.category)}</td><td>${e.source==='boss'?pill('老板直接代付','info'):name('accounts',e.accountId)}</td><td class="right">${amount(e.amount)}</td><td>${esc(e.note||'—')}</td></tr>`)))+`<div style="height:20px"></div>`+panel('发票明细',table(['发票日期 / 号码','业务方向','交易对方','不含税金额','税额','价税合计'],state.invoices.filter(inMonth).sort(byDate).map(i=>`<tr><td>${i.date}<span class="muted">${esc(i.number)}</span></td><td>${esc(i.direction)}</td><td>${esc(i.partner)}</td><td class="right">${cash(i.base)}</td><td class="right">${cash(i.tax)}</td><td class="right">${cash(i.base+i.tax)}</td></tr>`)),'','登记实际发票不会自动计算或重复扣减月度税费');}
function profit(){const s=summary(state,ui.month);const rs=state.recognitions.filter(inMonth).sort(byDate);return pageHead('REPORTS / PROFIT','利润报表',`${ui.month} · 回款及余额抵扣确认销售利润，退货和补差单列`,btn('运费补差','freight_adjust')+btn('填写本月税费','tax','primary'))+`<div class="kpi-grid">${kpi('已确认销售利润',s.salesProfit,'整单毛利 × 本次款项覆盖比例','profit')}${kpi('本月公司费用',s.expenses,'按实际付款月份计入','expenses')}${kpi('本月手工税费',s.tax,state.taxes[ui.month]===undefined?'尚未填写，结果待完善':'仅扣一次，不自动算税','expenses')}${kpi('本月公司利润',s.profit,'含退货冲回及运费调整','profit',true)}</div><div class="dashboard-grid"><div class="dashboard-main">${panel('销售利润确认明细',table(['确认日期','销售单 / 客户','本次款项覆盖','本次确认利润'],rs.map(r=>{const sale=get('sales',r.saleId);return `<tr><td>${r.date}</td><td><button class="text-button" data-action="saleDetail" data-id="${r.saleId}">${esc(r.saleId)}</button><span class="muted">${name('customers',sale?.customerId)}</span></td><td class="right">${cash(r.amount)}</td><td class="right ${r.profit>=0?'positive':'negative'}">${cash(r.profit)}</td></tr>`})),pill(`${rs.length} 条`))}${panel('当月调整',table(['日期','关联销售','调整项目','扣减金额'],state.adjustments.filter(inMonth).map(a=>`<tr><td>${a.date}</td><td>${esc(a.saleId||'—')}</td><td>${esc(a.note||a.kind)}</td><td class="right">${cash(a.amount)}</td></tr>`)),'','月结运费补差在当月调整，保留原月份报表')}</div><div class="dashboard-rail">${panel('利润从哪里来',profitBreakdown(s))}${panel('计算口径',`<div class="panel-body"><p class="invoice-note">商品销售利润 = 销售价 − 实际采购成本 − 进货运费 − 销售运费。</p><p class="invoice-note">回款按销售日期从早到晚分配；部分回款按覆盖比例确认。客户余额抵扣使用新货成本，不增加银行回款。</p><p class="invoice-note">老板垫资、还本金、内部转账不直接计入利润。报表基于本测试账本的已保存业务。</p></div>`)}</div></div>`;}
function imports(){
  const owner=session.user.role==='owner', closed=state.closedMonths.includes(ui.month);
  return pageHead('DATA / WORKSPACE','导入与设置','共享账本、成员权限和基础资料',btn('刷新账本','refresh')+(owner?btn('导出业务副本','export'):''))
  +`<div class="two-column"><div class="stack">${panel('基础资料',`<div class="panel-body"><p class="invoice-note">先建立客户、供应商和商品，再登记采购与销售。当前支持有唯一串号的商品。</p><div class="settings-actions">${btn('新增客户','masterCustomers')}${btn('新增供应商','masterSuppliers')}${btn('新增商品','masterProducts')}${owner?btn('账户命名','account_rename'):''}</div><p class="invoice-note">客户 ${state.customers.length} 个 · 供应商 ${state.suppliers.length} 个 · 商品 ${state.products.length} 个</p></div>`)}${panel('博远资料导入',`<div class="panel-body"><div class="notice">真实 Excel 导入尚在开发。此版本可手工录入测试业务；原始表格未上传到服务器。</div><p class="invoice-note">下一步接入采购日报、销售／退货日报、入库串号查询和批量串号跟踪，并校验重复单据与串号关联。</p></div>`)}</div><div class="stack">${panel('账号与账期',`<div class="panel-body"><div class="settings-row"><div><strong>${esc(session.user.name)} · ${ui.role}</strong><small>权限由服务端校验</small></div>${btn('修改密码','password','ghost small')}</div>${owner?`<div class="settings-row"><div><strong>内部成员</strong><small>为老板或财务分别开通账号</small></div>${btn('成员管理','users','secondary small')}</div>`:''}<div class="settings-row"><div><strong>${ui.month} ${closed?'已关账':'未关账'}</strong><small>关账后禁止写入；老板填写原因后可反关账</small></div>${owner?btn(closed?'反关账':'关账','toggleClose','secondary small'):pill('老板管理')}</div></div>`)}${panel('保存与记录',`<div class="panel-body"><p class="invoice-note">当前账本版本：${revision}。每次保存同时写入操作者、业务内容与变更前后值。</p><p class="invoice-note">数据库备份和恢复已提供管理员命令；业务副本不含登录账号，不能直接作为整库恢复文件。</p>${owner?btn('查看操作审计','audit'):''}</div>`)}</div></div><div style="height:20px"></div>`
  +panel('最近业务操作',table(['业务日期','操作类型','操作者','说明'],[...state.audit].slice(-12).reverse().map(a=>`<tr><td>${esc(a.date)}</td><td>${esc(typeNames[a.type]||a.type)}</td><td>${esc(a.actorName||'初始示例')}</td><td>${esc(a.note||'—')}<span class="muted">${esc(a.id)}</span></td></tr>`)));
}

function render(){ui.page=Object.hasOwn(names,location.hash.slice(1))?location.hash.slice(1):'overview';document.querySelector('#nav').innerHTML=Object.entries(names).map(([p,n])=>`<a class="nav-item ${ui.page===p?'active':''}" href="#${p}" ${ui.page===p?'aria-current="page"':''}>${icon(p)}<span>${n}</span>${p==='purchases'?`<span class="nav-badge">${state.purchases.filter(x=>x.status!=='received').length}</span>`:''}</a>`).join('');document.querySelector('#crumb').textContent=names[ui.page];document.querySelector('#roleName').textContent=session.user.name+' · '+ui.role;document.querySelector('.sync-status').textContent='账本版本 '+revision;document.querySelector('#main').innerHTML=({overview,accounts,purchases,sales,inventory,expenses,profit,imports}[ui.page])();}

const field=(label,name,content,full=false,hint='')=>`<div class="field ${full?'full':''}"><label for="f-${name}">${label}</label>${content}${hint?`<small>${hint}</small>`:''}</div>`;
const input=(name,type='text',value='',extra='')=>`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`;
const select=(name,options)=>`<select id="f-${name}" name="${name}">${options}</select>`;
const moneyField=(label='金额',name='amount',value='',zero=false)=>field(label+'（元）',name,input(name,'number',value,`required min="${zero?0:0.01}" step="0.01" inputmode="decimal"`));
const dateField=()=>field('业务日期','date',input('date','date',currentDate(),'required'));
const accountField=(label='收付款账户',selected='')=>field(label,'accountId',select('accountId',accountOptions(selected)));
const noteField=()=>field('备注','note',input('note','text','','maxlength="120" placeholder="可选，便于后续核对"'),true);
const customerField=(id='')=>field('客户','customerId',select('customerId',entityOptions('customers',id)));
const supplierField=(id='')=>field('供应商','supplierId',select('supplierId',entityOptions('suppliers',id)));
const categories=['工资','房租','办公费用','人情往来','资金使用成本','其他日常支出'];
const categoryField=()=>field('费用类别','category',select('category',categories.map(x=>`<option>${x}</option>`).join('')));
const modal=document.querySelector('#modal');let modalAction='',modalId='';
function dialog(title,body,foot='',subtitle=''){modal.innerHTML=`<div class="modal-head"><div><h2 id="modalTitle">${title}</h2>${subtitle?`<p class="muted">${subtitle}</p>`:''}</div><button class="close-modal" aria-label="关闭弹窗" data-action="close">×</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;if(!modal.open)modal.showModal();}
function formDialog(type,id=''){modalAction=type;modalId=id;let title='',sub='',fields='';const date=dateField(),amt=moneyField();
  switch(type){
    case 'receipt':title='登记客户回款';sub='只填总金额，系统自动从最早销售开始抵扣';fields=customerField(id)+accountField('实际收款账户')+amt+date;break;
    case 'transfer':title='账户内部转账';sub='账户总资金不变，不计利润，也不增加老板垫款';fields=field('转出账户','fromId',select('fromId',accountOptions()))+field('转入账户','toId',select('toId',accountOptions('acc-corp-2')))+amt+date;break;
    case 'boss_in':title='老板从外部垫入';sub='增加公司账户余额及欠老板本金';fields=accountField('实际收款账户')+amt+date;break;
    case 'boss_pay':title='老板直接代付公司费用';sub='不生成公司银行流水，增加欠老板金额并登记费用';fields=categoryField()+amt+date;break;
    case 'boss_repay':title='归还老板垫款';sub=`当前公司欠老板 ${cash(state.bossOwed)}；归还本金不重复扣利润`;fields=accountField('实际付款账户')+amt+date;break;
    case 'supplier_pay':title='向上游预付货款';sub='付款减少银行余额，增加上游可用余额';fields=supplierField(id)+accountField('实际付款账户')+amt+date;break;
    case 'expense':title='登记公司日常费用';sub='按实际付款月份扣减，不再登记已计入商品成本的运费';fields=categoryField()+accountField('实际付款账户')+amt+date;break;
    case 'tax':title='填写月度税费';sub='手工填写，扣减所选月份利润；保存此项不会生成银行付款';fields=field('归属月份','month',input('month','month',ui.month,'required'))+moneyField('税费','amount',(state.taxes[ui.month]||0)/100,true);break;
    case 'freight_adjust':title='快递月结补差';sub='当前支持已收齐销售的追加运费，调整当月利润并保留原月报表';fields=field('原销售单','saleId',select('saleId',state.sales.filter(s=>s.paid>=s.amount&&!s.returned).map(s=>`<option value="${s.id}">${s.id} · ${s.date} · ${name('customers',s.customerId)}</option>`).join('')))+moneyField('追加运费','amount','2')+date;break;
    case 'purchase_lock':title='登记上游锁货';sub='按锁货金额扣减上游可用余额，后续收货不再扣一次';fields=supplierField()+field('商品','productId',select('productId',entityOptions('products')))+field('数量（台）','qty',input('qty','number','10','required min="1" max="1000" step="1"'))+moneyField('约定单价','unitPrice','3250')+date;break;
    case 'purchase_ship':{const p=get('purchases',id);title='确认上游已发货';sub=`${p.id} · ${name('products',p.productId)} · ${p.qty} 台`;fields=date;break;}
    case 'purchase_receive':{const p=get('purchases',id);title='确认采购入库';sub=`${p.id} · ${name('products',p.productId)} · ${p.qty} 台`;fields=date+moneyField('整批进货运费','freight','38',true)+field(`商品串号（需要 ${p.qty} 个）`,'sns',`<textarea id="f-sns" name="sns" required placeholder="每行一个串号"></textarea>${state.mode==='demo'?'<button type="button" class="text-button" data-action="sampleSN" style="margin-top:8px">填入演示串号</button>':''}`,true,'串号对应实际货品，运费按数量分摊。按实际收货填写。');break;}
    case 'sale_create':title='登记销售出库';sub='销售运费直接填写；客户可用余额自动抵扣，使用本台商品实际成本';fields=customerField(id)+field('在库商品','inventoryId',select('inventoryId',state.inventory.filter(i=>i.status==='in_stock').map(i=>`<option value="${i.id}">${name('products',i.productId)} · ${esc(i.sn)} · 成本 ${cash(i.cost)}</option>`).join('')))+moneyField('销售金额','amount','3300')+moneyField('销售运费','freight','12',true)+date;break;
    case 'sale_return':{const s=get('sales',id);title='客户退货入库';sub=`${s.id} · ${name('customers',s.customerId)} · 按原售价 ${cash(s.amount)} 退货`;fields=date+`<div class="notice field full">商品回库，客户账单冲减 ${cash(s.amount)}；多出的余额留待下次拿货。已确认利润在退货月冲回，实际运费保留为损失。</div>`;break;}
    case 'invoice':title='登记实际发票';sub='记录票面信息，不自动生成月度税费扣减';fields=field('方向','direction',select('direction','<option>采购收票</option><option>销售开票</option>'))+field('发票号码','number',input('number','text','','required maxlength="40"'))+field('交易对方','partner',input('partner','text','','required maxlength="60"'))+date+moneyField('票面不含税金额','base','',true)+moneyField('票面税额','taxAmount','',true);break;
  }
  if(['masterCustomers','masterSuppliers','masterProducts'].includes(type)){
    const kind={masterCustomers:'customers',masterSuppliers:'suppliers',masterProducts:'products'}[type];
    title={customers:'新增客户',suppliers:'新增供应商',products:'新增串号商品'}[kind];modalAction='master_create';
    fields=field('名称','name',input('name','text','','required maxlength="80"'))+`<input type="hidden" name="kind" value="${kind}">`;
  }
  if(type==='account_rename'){title='账户命名';fields=accountField('业务账户')+field('新名称','name',input('name','text','','required maxlength="60"'));}
  if(['close_month','reopen_month'].includes(type)){title=type==='close_month'?'月份关账':'月份反关账';sub='请在备注填写原因，操作会留痕';fields=field('账期','month',input('month','month',ui.month,'required'));}
  if(!title)return;
  dialog(title,`<form id="actionForm"><div class="form-grid">${fields}${noteField()}</div><div id="formPreview" class="preview-box"></div><div id="formError" class="error-message" role="alert"></div><div class="modal-foot" style="padding:20px 0 0;border:0">${btn('取消','close')}<button class="button primary" type="submit">保存到账本</button></div></form>`,'',sub);updatePreview();
}
function updatePreview(){const f=document.querySelector('#actionForm');if(!f)return;const data=Object.fromEntries(new FormData(f));let text='';const v=Math.round(Number(data.amount||0)*100);if(modalAction==='receipt'){const c=get('customers',data.customerId);let remain=v;const sales=state.sales.filter(s=>s.customerId===c?.id&&!s.returned&&s.paid<s.amount&&s.date<=data.date).sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id,undefined,{numeric:true}));let rows=[],profit=0;for(const s of sales){const a=Math.min(remain,s.amount-s.paid);if(a<=0)break;profit+=proportionalProfit(s.amount-s.cost-s.originalFreight,s.paid+a,s.amount)-s.recognizedProfit;rows.push(`<div class="preview-row"><span>${s.date} · ${s.id}</span><strong>${cash(a)}</strong></div>`);remain-=a;}text=`<h3>自动抵扣预览</h3><div class="allocation-preview">${rows.join('')||'<span class="muted">填写金额后显示抵扣顺序</span>'}</div><div class="preview-row"><span>本次确认商品利润</span><strong class="positive">${cash(profit)}</strong></div>${remain>0?`<div class="preview-row"><span>留作客户可用余额</span><strong>${cash(remain)}</strong></div>`:''}`;}else if(modalAction==='purchase_receive'){const p=get('purchases',modalId);const freight=Math.round(Number(data.freight||0)*100);text=`<div class="preview-row"><span>采购单价</span><strong>${cash(p.unitPrice)}</strong></div><div class="preview-row"><span>每台分摊运费（平均）</span><strong>${cash(freight/p.qty)}</strong></div><div class="preview-row"><span>每台到货成本（平均）</span><strong>${cash(p.unitPrice+freight/p.qty)}</strong></div><small class="muted">入库不会再次扣减上游可用余额，尾差保留到分。</small>`;}else if(modalAction==='sale_create'){const i=get('inventory',data.inventoryId);const c=get('customers',data.customerId);text=`<div class="preview-row"><span>本台商品到货成本</span><strong>${cash(i?.cost||0)}</strong></div><div class="preview-row"><span>整单商品销售利润</span><strong>${cash(v-(i?.cost||0)-Math.round(Number(data.freight||0)*100))}</strong></div><div class="preview-row"><span>客户已有余额可覆盖</span><strong>${cash(Math.min(v,Math.max(0,-(c?.balance||0))))}</strong></div>`;}else if(modalAction==='purchase_lock'){const total=Math.round(Number(data.unitPrice||0)*100)*Number(data.qty||0);text=`<div class="preview-row"><span>本次锁货扣减</span><strong>${cash(total)}</strong></div><div class="preview-row"><span>锁货后上游可用</span><strong>${cash((get('suppliers',data.supplierId)?.available||0)-total)}</strong></div>`;}else if(modalAction==='invoice'){text=`<div class="preview-row"><span>价税合计</span><strong>${cash(Math.round((Number(data.base||0)+Number(data.taxAmount||0))*100))}</strong></div><small class="muted">按实际票面填写；月度税费另行手录。</small>`;}else if(modalAction==='tax'){text=`<div class="preview-row"><span>${esc(data.month)} 利润扣减</span><strong>${cash(v)}</strong></div><small class="muted">更新已有税费金额，不重复叠加；不改变银行余额。</small>`;}else if(modalAction==='transfer'){text='<div class="preview-row"><span>账户总资金变动</span><strong>¥0.00</strong></div><div class="preview-row"><span>公司欠老板及利润变动</span><strong>¥0.00</strong></div>';}else{text='<span class="muted">保存后将同步更新相关余额及明细。服务端保存成功后才会生效。</span>';}if(modalAction==='receipt'&&v>0&&data.date){try{applyAction(state,{type:'receipt',customerId:data.customerId,accountId:data.accountId,amount:v,date:data.date});}catch(e){text='<div class="error-message">'+esc(e.message)+'</div>';}}document.querySelector('#formPreview').innerHTML=text;}
async function submitForm(f){
  if(submitting)return;
  const data=Object.fromEntries(new FormData(f)),action={...data,type:modalAction};
  const button=f.querySelector('[type="submit"]');submitting=true;button.disabled=true;
  try{
    for(const k of ['amount','unitPrice','freight','base','taxAmount'])if(k in action)action[k]=yuanToCents(action[k]);
    if('qty'in action)action.qty=Number(action.qty);
    if('sns'in action)action.sns=action.sns.split(/[\s,，;；]+/).filter(Boolean);
    if(modalAction.startsWith('purchase_')&&modalId)action.purchaseId=modalId;
    if(modalAction==='sale_return')action.saleId=modalId;
    const result=await saveCommand(action);modal.close();render();toast(result.replayed?'这笔业务已经保存，已读取最新账本':'已保存，余额与利润已更新');
  }catch(e){f.querySelector('#formError').textContent=e.message;}
  finally{submitting=false;button.disabled=false;}
}
function saleDetail(id){const s=get('sales',id);const recs=state.recognitions.filter(r=>r.saleId===id);dialog('销售明细',`<dl class="detail-grid">${[['销售单',s.id],['客户',get('customers',s.customerId)?.name],['串号',s.sn],['销售金额',cash(s.amount)],['货品到货成本',cash(s.cost)],['初始销售运费',cash(s.originalFreight)],['已收／已抵扣',cash(s.paid)],['累计确认商品利润',cash(s.recognizedProfit)]].map(([k,v])=>`<div class="detail-item"><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${statusSale(s)}<h3 style="font-size:14px;margin-top:22px">利润确认记录</h3>${table(['日期','覆盖金额','确认利润'],recs.map(r=>`<tr><td>${r.date}</td><td>${cash(r.amount)}</td><td>${cash(r.profit)}</td></tr>`))}`,btn('关闭','close'));}
function serialDetail(id){const i=get('inventory',id);const sale=state.sales.filter(s=>s.sn===i.sn).sort((a,b)=>a.date.localeCompare(b.date));dialog('串号轨迹',`<div class="notice"><strong>${esc(i.sn)}</strong><br>${name('products',i.productId)} · 到货成本 ${cash(i.cost)}</div><ul class="timeline"><li><strong>采购入库</strong><small>${esc(i.date||'期初库存')} · ${esc(i.purchaseId||'期初建账')}</small></li>${sale.map(s=>`<li><strong>销售出库 · ${name('customers',s.customerId)}</strong><small>${s.date} · ${s.id} · ${cash(s.amount)}</small></li>${s.returned?`<li><strong>客户退货回仓</strong><small>${s.returnedDate} · 客户账单冲减 ${cash(s.amount)}</small></li>`:''}`).join('')}<li><strong>当前状态：${i.status==='in_stock'?'在库':'已售'}</strong></li></ul>`,btn('关闭','close'));}
async function handleAction(action,id=''){
  if(['receipt','transfer','boss_in','boss_pay','boss_repay','expense','tax','freight_adjust','purchase_lock','purchase_ship','purchase_receive','sale_return','sale_create','supplier_pay','invoice','masterCustomers','masterSuppliers','masterProducts','account_rename','close_month','reopen_month'].includes(action)){formDialog(action,id);return;}
  switch(action){case 'close':if(submitting||pendingCommand){toast('请先确认当前保存结果');break;}modal.close();break;case 'accountDetail':ui.account=id;location.hash='accounts';render();break;case 'profitDetail':go('profit');break;case 'toPurchases':go('purchases');break;case 'customerFilter':ui.customer=ui.customer===id?'':id;render();break;case 'clearCustomer':ui.customer='';render();break;case 'saleDetail':saleDetail(id);break;case 'serialDetail':serialDetail(id);break;
  case 'purchaseDetail':{const p=get('purchases',id);dialog('采购入库详情',`<dl class="detail-grid">${[['采购单',p.id],['供应商',get('suppliers',p.supplierId)?.name],['数量',p.qty+' 台'],['采购单价',cash(p.unitPrice)],['整批进货运费',cash(p.freight)],['到货日期',p.receivedDate]].map(([k,v])=>`<div class="detail-item"><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="invoice-note">成本已分摊到本批各串号，入库没有再次扣减上游余额。</p>`,btn('查看库存','toInventory'));break;}
  case 'toInventory':modal.close();go('inventory');break;
  case 'sampleSN':{const p=get('purchases',modalId);document.querySelector('#f-sns').value=Array.from({length:p.qty},(_,i)=>`DEMO-${p.id.toUpperCase()}-${String(i+1).padStart(3,'0')}`).join('\n');updatePreview();break;}
  case 'bossMenu':dialog('老板往来',`<div class="preview-box"><div class="preview-row"><span>公司当前欠老板</span><strong>${cash(state.bossOwed)}</strong></div></div><div class="stack" style="margin-top:18px">${btn('老板从外部转入公司账户','boss_in','primary full-width')}${btn('老板在外部直接代付费用','boss_pay','secondary full-width')}${btn('公司归还老板本金','boss_repay','secondary full-width')}</div><p class="invoice-note">直接代付采购货款的完整关联将在正式版本补齐；此处演示外部垫入、代付公司费用和归还本金。</p>`);break;
  case 'refresh':await refresh(true);break;
  case 'switchRole':dialog('退出登录','<p>退出当前账号后，需要重新输入账号和密码。已保存业务保留在账本中。</p>',btn('取消','close')+btn('确认退出','logout','primary'));break;
  case 'logout':try{await api('logout',{});location.replace('/login.html');}catch(e){toast(e.message);}break;
  case 'toggleClose':if(session.user.role!=='owner'){toast('只有老板可以处理关账');break;}formDialog(state.closedMonths.includes(ui.month)?'reopen_month':'close_month');break;
  case 'export':try{const data=await api('export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='财务工作台-业务副本-'+currentDate()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){toast(e.message);}break;
  case 'users':await showUsers();break;
  case 'createUser':accountForm('create');break;
  case 'resetPassword':accountForm('reset',id);break;
  case 'password':accountForm('password');break;
  case 'activateUser':case 'deactivateUser':try{await api('users/update',{id,active:action==='activateUser'});await showUsers();}catch(e){toast(e.message);}break;
  case 'audit':try{const log=await api('audit');dialog('最近 100 条操作审计',`<p class="invoice-note">包含变更前后内容和哈希值；数据库管理员仍需妥善保管备份。</p><pre class="audit-json">${esc(JSON.stringify(log,null,2))}</pre>`,btn('关闭','close'));}catch(e){toast(e.message);}break;
  case 'help':dialog('可以怎样体验',`<ol class="check-list"><li>在首页登记客户回款，查看自动抵扣与利润变化。</li><li>进入上游与采购，对在途单确认入库并填写运费。</li><li>在账户流水中做一次内部转账或老板垫款。</li><li>登记销售或客户退货，观察欠款、库存和利润。</li><li>填写月度税费或运费补差，核对当月利润。</li></ol><div class="notice">这是联机测试版。账号和业务保存在服务器数据库；完整导入、期初建账、历史更正和 iPhone App 仍待开发。</div>`,btn('开始体验','close','primary'));break;
  }
}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a){e.preventDefault();handleAction(a.dataset.action,a.dataset.id||'');return;}const g=e.target.closest('[data-go]');if(g){go(g.dataset.go);}});
document.addEventListener('keydown',e=>{const g=e.target.closest('[data-go][role="button"]');if(g&&(e.key==='Enter'||e.key===' ')){e.preventDefault();go(g.dataset.go);}});
modal.addEventListener('submit',e=>{if(e.target.id!=='actionForm')return;e.preventDefault();submitForm(e.target);});modal.addEventListener('input',updatePreview);modal.addEventListener('change',updatePreview);modal.addEventListener('click',e=>{if(e.target===modal&&!submitting&&!pendingCommand){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;ui.search=e.target.value;render();const el=document.querySelector('#search');el?.focus();el?.setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{if(e.target.id==='accountFilter'){ui.account=e.target.value;render();}});
document.querySelector('#monthPicker').addEventListener('change',e=>{if(!e.target.value)return;ui.month=e.target.value;render();});
document.querySelector('#menuButton').addEventListener('click',()=>{document.querySelector('#sidebar').classList.add('open');document.querySelector('#overlay').classList.add('visible');});document.querySelector('#overlay').addEventListener('click',closeMenu);document.querySelector('#switchRole').addEventListener('click',()=>handleAction('switchRole'));document.querySelector('#helpButton').addEventListener('click',()=>handleAction('help'));window.addEventListener('hashchange',()=>{ui.search='';closeMenu();render();});render();

modal.addEventListener('cancel',event=>{if(submitting||pendingCommand)event.preventDefault();});
window.addEventListener('focus',()=>{if(!modal.open&&!submitting)refresh();});
setInterval(()=>{if(!document.hidden&&!modal.open&&!submitting)refresh();},30000);
async function showUsers(){
  try{const {users}=await api('users');dialog('内部成员',users.map(user=>`<div class="user-row"><div><strong>${esc(user.name)} · ${user.role==='owner'?'老板':'财务'}</strong><small>${esc(user.username)} · ${user.active?'正常':'已停用'}</small></div>${user.id===session.user.id?pill('当前账号'):('<div class="user-actions">'+btn('重置密码','resetPassword','ghost small',user.id)+btn(user.active?'停用':'启用',user.active?'deactivateUser':'activateUser','secondary small',user.id)+'</div>')}</div>`).join(''),btn('新增成员','createUser','primary'));}
  catch(e){toast(e.message);}
}
function accountForm(kind,id=''){
  const pass=field('新密码（至少 12 位）','password',input('password','password','','required minlength="12" maxlength="128" autocomplete="new-password"'));
  const confirm=field('再输入一次新密码','confirm',input('confirm','password','','required minlength="12" maxlength="128" autocomplete="new-password"'));
  let fields=pass+confirm;
  if(kind==='create')fields=field('姓名','name',input('name','text','','required maxlength="40"'))+field('账号','username',input('username','text','','required minlength="3" maxlength="40" pattern="[a-zA-Z0-9_.-]+" autocomplete="off"'))+field('权限','role',select('role','<option value="finance">财务</option><option value="owner">老板</option>'))+fields;
  if(kind==='password')fields=field('当前密码','currentPassword',input('currentPassword','password','','required autocomplete="current-password"'))+fields;
  dialog({create:'新增成员',reset:'重置成员密码',password:'修改我的密码'}[kind],`<form id="accountForm"><div class="form-grid">${fields}</div><p class="error-message" id="accountError" role="alert"></p><button type="submit" class="button primary">保存账号设置</button></form>`,'','密码更新后，该账号之前的登录会话立即失效。');
  document.querySelector('#accountForm').addEventListener('submit',async event=>{
    event.preventDefault();const form=event.target,button=form.querySelector('button');if(button.disabled)return;
    button.disabled=true;const data=Object.fromEntries(new FormData(form));
    try{if(data.password!==data.confirm)throw new Error('两次密码不一致');delete data.confirm;
      const result=await api(kind==='create'?'users':kind==='reset'?'users/update':'password',kind==='reset'?{id,password:data.password}:data);
      if(kind==='password')setCsrf(result.csrf);
      modal.close();toast('账号设置已保存');
    }catch(e){form.querySelector('#accountError').textContent=e.message;}finally{button.disabled=false;}
  });
}

window.addEventListener('beforeunload',event=>{if(submitting||pendingCommand){event.preventDefault();event.returnValue='';}});
